import { describe, expect, it } from 'vitest'
import {
  averageUnwindWeight,
  curveFor,
  takerPrice,
  unwindFullNgn,
  withLift,
} from './curve'
import cases from './unwindParity.json'

// Generated by tests/unwind_parity.rs from the bot's own unwind::shift,
// average_weight and Curve::with_lift, with the ask floored on the signed
// order and the venue fee added after. The panel's lifted curve must price
// exactly what the taker realizes.
type Case = {
  knobs: {
    share: number
    cap_ngn: number
    min_gain_ngn: number
    start_pct: number
  }
  cost: number
  feed_mid: number
  reference: { mid: number; half_range_bps: number }
  spread_bps: number
  fee_bps: number
  curve: { start_below_mid: number; end_above_buy: number; shape: number }
  stretch: [number, number]
  full_ngn: number
  gain: number
  average_weight: number
  bid: number
  ask: number
  plain_ask: number
}

const close = (got: number, want: number) =>
  expect(Math.abs(got - want)).toBeLessThanOrEqual(
    Math.max(Math.abs(want), 1) * 1e-9
  )

describe('the panel lifts the curve as the bot does', () => {
  it.each((cases as Case[]).map((c, i) => [i, c] as const))(
    'case %i',
    (_, c) => {
      const full = unwindFullNgn(c.knobs, {
        cost: c.cost,
        feed_mid: c.feed_mid,
      })
      close(full, c.full_ngn)
      const [f0, f1] = c.stretch
      close(averageUnwindWeight(f0, f1, c.knobs.start_pct), c.average_weight)
      const plain = curveFor(
        c.reference,
        c.spread_bps + c.fee_bps,
        c.curve,
        c.spread_bps
      )!
      const lifted = withLift(plain, {
        fullNgn: full,
        startPct: c.knobs.start_pct,
        costNgn: c.cost,
      })
      close(takerPrice(lifted, true, f0, f1), c.bid)
      close(takerPrice(lifted, false, f0, f1), c.ask)
      close(takerPrice(plain, false, f0, f1), c.plain_ask)
    }
  )
})
